public final class EuclideanAlgorithm {

    private EuclideanAlgorithm() {
        // Utility class.
    }

    public static int gcd(int a, int b) {
        long x = Math.abs((long) a);
        long y = Math.abs((long) b);

        if (x == 0) {
            return toIntExact(y);
        }
        if (y == 0) {
            return toIntExact(x);
        }

        while (y != 0) {
            long remainder = x % y;
            x = y;
            y = remainder;
        }

        return toIntExact(x);
    }

    @Deprecated
    public static int findGCD(int a, int b) {
        return gcd(a, b);
    }

    private static int toIntExact(long value) {
        if (value < Integer.MIN_VALUE || value > Integer.MAX_VALUE) {
            throw new ArithmeticException("GCD does not fit in an int: " + value);
        }
        return (int) value;
    }
}

public final class EuclideanAlgorithmApp {

    private static final int DEFAULT_A = 35;
    private static final int DEFAULT_B = 15;

    private EuclideanAlgorithmApp() {
        // Utility class.
    }

    public static void main(String[] args) {
        int[] operands = parseOperands(args);
        System.out.println(EuclideanAlgorithm.gcd(operands[0], operands[1]));
    }

    private static int[] parseOperands(String[] args) {
        if (args.length == 0) {
            return new int[] { DEFAULT_A, DEFAULT_B };
        }
        if (args.length != 2) {
            throw new IllegalArgumentException(
                "Expected either zero arguments or two integers: <a> <b>"
            );
        }

        return new int[] {
            parseIntArg(args[0], "first"),
            parseIntArg(args[1], "second")
        };
    }

    private static int parseIntArg(String value, String label) {
        try {
            return Integer.parseInt(value);
        } catch (NumberFormatException ex) {
            throw new IllegalArgumentException("Invalid " + label + " integer: " + value, ex);
        }
    }
}

public final class EuclideanAlgorithmTest {

    private EuclideanAlgorithmTest() {
        // Utility class.
    }

    public static void main(String[] args) {
        assertGcd(35, 15, 5);
        assertGcd(-42, 56, 14);
        assertGcd(0, 9, 9);
        assertGcd(9, 0, 9);
        assertGcd(0, 0, 0);
        assertOverflow(Integer.MIN_VALUE, 0);
    }

    private static void assertGcd(int a, int b, int expected) {
        int actual = EuclideanAlgorithm.gcd(a, b);
        if (actual != expected) {
            throw new AssertionError(
                "gcd(" + a + ", " + b + ") expected " + expected + " but was " + actual
            );
        }
    }

    private static void assertOverflow(int a, int b) {
        try {
            EuclideanAlgorithm.gcd(a, b);
        } catch (ArithmeticException expected) {
            return;
        }

        throw new AssertionError(
            "gcd(" + a + ", " + b + ") was expected to overflow but completed normally"
        );
    }
}

